pt:
//【一条】
<voice name='一条' class='一条' src='voice/mb04/0140320a02'>
//「ぐ……ッ！」
"Guh...!"

en:
//【正宗】
<voice name='正宗' class='正宗' src='voice/mb04/0140330b40'>
//《言うた通りの仕儀となったな。
//　所詮、悪鬼は悪鬼よ！》
《It is as I said. A demon will always be a demon!》

pt:
//【正宗】
<voice name='正宗' class='正宗' src='voice/mb04/0140330b40'>
